import React from 'react';
import { Link } from 'react-router-dom';

const Navbar = () => {
    return (
        <nav className="bg-blue-600 shadow-lg">
            <div className="max-w-6xl mx-auto px-4">
                <div className="flex justify-between">
                    <div className="flex space-x-4">
                        <div>
                            <Link to="/" className="flex items-center py-5 px-2 text-white text-lg font-bold hover:text-gray-200">
                                Home
                            </Link>
                        </div>
                        <div className="hidden md:flex items-center space-x-4">

                            <Link to="/jwtlogin" className="py-5 px-3 text-white hover:text-gray-200">login</Link>
                            <Link to="/jwtregister" className="py-5 px-3 text-white hover:text-gray-200">Register</Link>




                        </div>
                    </div>
                </div>
            </div>
        </nav>
    );
};

export default Navbar;
